    '''
    
    leapByte: Optional[ Seconds ] = field(
        default=None,
        metadata={
        'type': 'Attribute',
        'stereotypes': ['Attribute'],
        'minOccurs': '0',
        'maxOccurs': '1',
        'namespace': 'http://gridappsd.org/CIM/extension#',
        'serialize': True,
        })
    '''
