@stereotype(CIMStereotype.GridAPPSD)
@stereotype(CIMStereotype.Concrete)
@stereotype(CIMStereotype.Description)
@dataclass(repr=False, eq=False)
class TransformerPhaseEnd(TransformerEnd):
    '''
    The single-phase aggregation of physical lugs and jumpers on one side of
    a power transformer (composed of one or more transformer tanks) from the
    perspective of connectivity to the external network.
    The end number of each transformer phase end should match the end number
    of the power transformer end that is connected to the same Terminal such
    that phase ends on one side of the transformer all carry the same end number.
    The total number of phase ends should match the total number of phases
    of that side of the transformer, as indicated by the phase code of the
    terminal. For example, the low side of an open-wye/open-delta transformer
    with 4-wire ABCN service will have four transformer phase ends.
    '''

    sequenceNumber: Optional[int] = field(
        default=None,
        metadata={
        'type': 'Attribute',
        'stereotypes': ['Attribute'],
        'minOccurs': '0',
        'maxOccurs': '1',
        'namespace': 'http://gridappsd.org/CIM/extension#',
        'serialize': True,
        })
    '''
    The position of this phase end among the phase ends of its power transformer,
    starting at 1. The order should match the order of the phases in the
    associated Terminal�s phases, with the neutral last.
    For example, two-winding transformer with a high-side terminal with
    phases BN is sequenced B=1, N=2, and low-side terminal with phases
    s1s2N is sequenced s1=3, s2=4, N=5. A phase end is identified within
    the transformer by the combination of its end number and sequence number.
    '''
    
    phase: Optional[ SinglePhaseKind ] = field(
        default=None,
        metadata={
        'type': 'Attribute',
        'stereotypes': ['ShadowExtension', 'enumeration', 'Attribute'],
        'minOccurs': '0',
        'maxOccurs': '1',
        'namespace': 'http://gridappsd.org/CIM/extension#',
        'serialize': True,
        })
    '''
    The single phase of the aggregation of all lugs connected together
    to form the terminal-facing connection on this side of the transformer.
    '''
    
    phaseNeutralU: Optional[ Voltage ] = field(
        default=None,
        metadata={
        'type': 'Attribute',
        'stereotypes': ['Attribute'],
        'minOccurs': '0',
        'maxOccurs': '1',
        'namespace': 'http://gridappsd.org/CIM/extension#',
        'serialize': True,
        })
    '''
    The no-load voltage of this single phase relative to the neutral of
    the connected end. It is the phase-to-neutral voltage, which is not
    necessarily equal to the phase-to-phase rated voltage divided by v3.
    For example, a 12470 V wye primary has 7200 V on each phase, a 120/240
    V split-phase secondary has 120 V on s1 and on s2, and the high leg
    of a open-delta secondary has a no-load voltage of about 208 V. The
    neutral phase end (N) has a value of 0 V.
    '''
    
    @property
    def __namespace__(self):
        return 'http://gridappsd.org/CIM/extension#'
    @property
    def __package__(self):
        return 'WiresEXT'
    @property
    def __minOccurs__(self):
        return '0'
    @property
    def __maxOccurs__(self):
        return 'unbounded'
    
