    ToMeshImpedance: list[TransformerMeshImpedance] = field(
        default_factory=list,
        metadata={
        'type': 'Association',
        'stereotypes': [],
        'minOccurs': '0',
        'maxOccurs': 'unbounded',
        'inverse': 'TransformerMeshImpedance.ToWinding',
        'namespace': 'http://cim.ucaiug.io/cim101/draft#',
        'serialize': False,
        })
    '''
    All mesh impedances between this "to" and other "from" transformer
    windings.
    '''
    
    TransformerCore: Optional[TransformerCore] = field(
        default=None,
        metadata={
        'type': 'Association',
        'stereotypes': ['new'],
        'minOccurs': '0',
        'maxOccurs': '1',
        'inverse': 'TransformerCore.TransformerWindings',
        'namespace': 'http://cim.ucaiug.io/cim101/draft#',
        'serialize': True,
        })
    '''
    '''
    
